"""Build a standalone, offline Traditional Chinese experiment viewer."""
import argparse,json
from pathlib import Path

PAGE=r'''<!doctype html>
<html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MERIT｜免訓練實驗筆記</title>
<style>
:root{--ink:#172e38;--muted:#526873;--line:#dbe4e6;--green:#166452;--red:#a63d39;--paper:#f5f8f7}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.75 system-ui,-apple-system,"PingFang TC",sans-serif}main{max-width:1280px;margin:auto;padding:42px 28px}header{padding:30px 0;border-bottom:1px solid var(--line)}small,.muted{color:var(--muted)}.eyebrow{font-size:13px;letter-spacing:.14em;color:var(--green)}h1{font-size:clamp(30px,5vw,52px);letter-spacing:-.04em;line-height:1.2;margin:14px 0}h2{font-size:25px;margin:30px 0 14px}h3{margin:6px 0}p{max-width:850px}.tag{display:inline-block;padding:3px 10px;border:1px solid var(--line);border-radius:20px;font-size:13px;margin:0 6px 5px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:26px 0}.card{background:white;border:1px solid var(--line);border-radius:14px;padding:20px}.number{font-size:30px;font-weight:650}.filters{display:flex;flex-wrap:wrap;gap:14px;align-items:end;padding:18px;background:#eaf0ee;border-radius:12px}label{font-size:13px;display:flex;flex-direction:column;gap:5px}select,input,button{font:inherit;padding:8px 12px;border:1px solid #b8c9c7;border-radius:7px;background:white;color:var(--ink)}button{cursor:pointer}button:hover{background:#eaf0ee}select:focus,button:focus,input:focus{outline:3px solid #91bdb2}.scroll{overflow:auto;background:white;border:1px solid var(--line);border-radius:12px;margin:16px 0}table{border-collapse:collapse;width:100%;white-space:nowrap;font-size:14px}th,td{padding:11px 14px;text-align:right;border-bottom:1px solid var(--line)}th{background:#edf3f1;font-size:12px;color:var(--muted)}th:first-child,td:first-child{text-align:left}tr:last-child td{border-bottom:0}.positive{color:var(--green)}.negative{color:var(--red)}.note{padding:16px 20px;border-left:3px solid #789c91;background:#edf3ef;margin:18px 0}.chart-row{display:grid;grid-template-columns:210px 1fr 75px;gap:15px;align-items:center;margin:10px 0;font-size:14px}.track{background:#e5eeeb;border-radius:5px;overflow:hidden;height:20px}.bar{height:100%;background:#368371}.explain{display:grid;grid-template-columns:1fr 1fr;gap:16px}details{border:1px solid var(--line);background:white;padding:16px;border-radius:10px;margin:14px 0}summary{cursor:pointer;font-weight:600}a{color:var(--green)}footer{color:var(--muted);font-size:13px;padding:30px 0}.case-tools{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.case-top{max-width:400px;white-space:normal;word-break:break-word}#caseTable td{white-space:normal;min-width:75px}#caseTable td:first-child{min-width:210px}@media(max-width:720px){main{padding:20px 14px}.cards,.explain{grid-template-columns:1fr}.chart-row{grid-template-columns:140px 1fr 60px}.filters label{width:calc(50% - 10px)}select{width:100%}.number{font-size:25px}}
</style></head><body><main>
<header><div class="eyebrow">MERIT RESEARCH / 2026.09</div><h1>不訓練模型，也要把改善的原因說清楚。</h1><p>先檢查尺度，再看污染、延遲和早期觀測，最後比較排序方式與 RE1。這個頁面讓你看到每個實驗做了什麼、為什麼做，以及哪些案例改對或改錯。</p><span class="tag">正式方法保留 victim</span><span class="tag">全程免訓練</span><span class="tag">開發期／跨資料集證據</span><span class="tag">不自動更換預設</span></header>
<section class="cards"><div class="card"><small>不同故障案例</small><div class="number" id="nCases"></div><small>RE2 + RE1；重複執行不算新案例</small></div><div class="card"><small>實際實驗記錄</small><div class="number" id="nRecords"></div><small>共用基準的顯示列不重複計數</small></div><div class="card"><small>錯誤／不適用記錄</small><div class="number" id="nErrors"></div><small>保留並揭露，沒有悄悄刪除</small></div></section>
__FINDINGS__
<section><h2>每組實驗做了什麼，為什麼這樣做？</h2><div class="explain"><div class="card"><h3>① 是 std 好，還是原來的 fallback 有問題？</h3><p>四組只改分母：原版、只修 IQR=0、只改正 IQR、全部改 std。中心都保留 median。</p></div><div class="card"><h3>② 異常混入正常資料，還準嗎？</h3><p>把正常樣本數的 5%、10%、20% 個故障初期樣本加入 metric 基線；待診斷的異常窗口不變。這是隔離原因的實驗。</p></div><div class="card"><h3>③ 晚發現、或只看幾分鐘，會怎樣？</h3><p>延遲 60／120／180 秒會移動方法切分時間；早期觀測只開放故障後 60／180／300 秒，metrics 和 traces 使用同一截止時間。</p></div><div class="card"><h3>④ 更好的 metric 還需要後段排序嗎？</h3><p>同一份 metric 證據，分別用完整 MERIT、直接排序及 singleton。另在 RE1 固定公式驗證，沒有看結果再調參。</p></div></div></section>
<h2>結果探索</h2><div class="filters"><label>資料集<select id="dataset"></select></label><label>實驗組別<select id="group"></select></label><label>實驗條件<select id="condition"></select></label><label>故障類型<select id="fault"></select></label><label>圖表指標<select id="metric"><option>AC@1</option><option>AC@3</option><option>AC@5</option><option>AVG@5</option></select></label></div>
<div id="why" class="note"></div><div id="chart" aria-label="所選定位指標長條圖"></div>
<div class="scroll"><table id="resultTable"><thead><tr><th>方法</th><th>有效／全部</th><th>AC@1</th><th>AC@3</th><th>AC@5</th><th>AVG@5</th><th>ΔAC@1 [95% CI] pp</th><th>相對自身乾淨完整窗口 ΔAC@1 pp</th><th>改對／改錯</th><th>候選召回</th><th>錯誤／不適用</th></tr></thead><tbody></tbody></table></div>
<p class="muted">AC@1／3／5：真正根因排進前 1／3／5 名的比例。AVG@5：AC@1 到 AC@5 的平均，越高代表根因通常排得越前。數值按故障類型等權平均。</p>
<details><summary>比較基準、統計區間與執行時間怎麼看？</summary><p>尺度、污染、延遲及時間實驗的 Δ 是「相同條件下，該方法減原版」；後段排序的 Δ 是「該排序減同尺度的完整 MERIT」。改對／改錯只指第一名。污染、延遲、短窗口相對乾淨完整窗口的退步另存 analysis.json 的 clean_delta。</p><p>區間使用 5,000 次依故障類型分層、服務×故障為群組的配對 bootstrap；同一故障的重複注入一起抽樣。區間未做多重比較校正，不能當成獨立驗證的保證。缺乏足夠時間資料列為不適用；執行錯誤則計為定位失敗。直接排序沒有 game 候選召回。</p><p>完整方法呼叫與研究 core／直接矩陣運算的計時範圍不同；本頁不將它們排成速度名次，原始時間保留在逐案記錄。</p></details>
<h2>哪些案例改對、哪些改錯？</h2><div class="case-tools"><label>方法<select id="caseArm"><option value="ALL">全部</option></select></label><label>案例狀態<select id="caseState"><option value="ALL">全部</option><option value="fixed">第一名改對</option><option value="broken">第一名改錯</option><option value="problem">錯誤／不適用</option></select></label><label>搜尋案例<input id="search" placeholder="例如 travel、cpu" aria-label="搜尋案例"></label><button id="download">下載目前篩選 CSV</button></div><p id="caseCount" class="muted"></p><div class="scroll"><table id="caseTable"><thead><tr><th>案例</th><th>方法</th><th>根因名次</th><th>狀態</th><th>前五名</th></tr></thead><tbody></tbody></table></div>
<section class="note"><strong>證據的界線</strong><p>RE2 已用於前輪方法開發；專案也已有 RE1 實驗紀錄，所以 RE1 是固定公式後的跨資料集檢查，並非宣稱從未看過的測試集。沒有根因標籤參與打分、沒有依系統或故障類型選擇專屬公式。原始公式的數學性質與定位準確率是不同層次的證據。</p><p id="overlap"></p></section>
<footer>本頁可離線開啟，資料直接內嵌。完整來源、輸入雜湊、所有矩陣與逐案記錄保存在同一實驗資料夾。<a href="README.md">重現說明</a> · <a href="analysis.json">完整分析 JSON</a> · <a href="cases.csv">全部案例 CSV</a></footer>
</main><script id="payload" type="application/json">__DATA__</script><script>
'use strict';const DATA=JSON.parse(document.getElementById('payload').textContent);
if(DATA.info.smoke)document.querySelector('h1').textContent='試跑預覽：僅供網頁功能檢查';
const $=id=>document.getElementById(id),labels={original:'原版 median/IQR',median_std:'median/std',fallback_only:'只修 IQR=0 分母',positive_only:'只改正 IQR 分母'},groups={scale:'尺度拆解／RE1 驗證',pollution:'基線污染',delay:'偵測延遲',horizon:'觀察時間',backend:'後段排序'},backends={full:'完整 MERIT',direct:'直接 metric 排序',singleton:'Singleton'};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function options(id,values,names={}){let old=$(id).value;$(id).innerHTML=values.map(v=>`<option value="${escape(v)}">${escape(names[v]||v)}</option>`).join('');if(values.includes(old))$(id).value=old;}
function conditionName(g,c){if(g==='backend')return backends[c];if(c==='full')return '完整紀錄';if(g==='pollution')return c==='0'?'乾淨基線':`${Number(c)*100}% 加入樣本`;return c==='0'?'無延遲':`${c} 秒`;}
function selected(){return DATA.summary.filter(r=>r.dataset===$('dataset').value&&r.group===$('group').value&&r.condition===$('condition').value&&r.fault===$('fault').value);}
function cascade(level){let ds=$('dataset').value;if(level<=1)options('group',[...new Set(DATA.summary.filter(r=>r.dataset===ds).map(r=>r.group))].sort((a,b)=>Object.keys(groups).indexOf(a)-Object.keys(groups).indexOf(b)),groups);let g=$('group').value;if(level<=2){let cs=[...new Set(DATA.summary.filter(r=>r.dataset===ds&&r.group===g).map(r=>r.condition))];cs.sort((a,b)=>a==='full'?-1:b==='full'?1:Number(a)-Number(b));options('condition',cs,Object.fromEntries(cs.map(c=>[c,conditionName(g,c)])));}let rs=DATA.summary.filter(r=>r.dataset===ds&&r.group===g&&r.condition===$('condition').value);options('fault',['ALL',...[...new Set(rs.map(r=>r.fault))].filter(f=>f!=='ALL').sort()],{ALL:'全部故障（等權）'});render();}
function pct(x){return x==null?'—':`${(x*100).toFixed(2)}%`;}
function render(){let rs=selected(),g=$('group').value;let why={scale:'只改分母，其他流程固定。RE1 的三個資料夾以相同公式驗證，不重新調參。',pollution:'加入的樣本數以原正常窗口長度為分母；異常觀測不变。比較基準是相同污染程度下的原版。',delay:'切分時間變晚，metric 基線與 trace 呼叫圖基線都可能受影響。比較基準是相同延遲下的原版。',horizon:'越短的窗口越接近早期診斷。沒有足夠資料的案例明列不適用，不把截短紀錄冒充完整時長。',backend:'比較基準是同一尺度下的完整 MERIT。直接排序只用相同 metric 服務證據；singleton 使用相同候選、矩陣與權重。'};$('why').textContent=why[g];
let metric=$('metric').value;$('chart').innerHTML=rs.map(r=>{let v=r.metrics?.[metric]?.value;return `<div class="chart-row"><span>${escape(labels[r.arm])}</span><div class="track"><div class="bar" style="width:${v==null?0:100*v}%"></div></div><strong>${pct(v)}</strong></div>`;}).join('');
$('resultTable').querySelector('tbody').innerHTML=rs.map(r=>{let d=r.delta?.['AC@1'];let text=d?`${d.value>=0?'+':''}${(100*d.value).toFixed(2)} [${(100*d.ci[0]).toFixed(2)}, ${(100*d.ci[1]).toFixed(2)}]`:'—';let clean=r.clean_delta?.['AC@1'];return `<tr><td>${escape(labels[r.arm])}</td><td>${r.valid}/${r.n}</td>${['AC@1','AC@3','AC@5','AVG@5'].map(m=>`<td>${pct(r.metrics?.[m]?.value)}</td>`).join('')}<td class="${d?.value>0?'positive':d?.value<0?'negative':''}">${text}</td><td>${clean?(clean.value*100).toFixed(2):'—'}</td><td>${r.fixed}/${r.broken}</td><td>${pct(r.candidate_recall)}</td><td>${r.errors}/${r.unsupported}</td></tr>`;}).join('');
options('caseArm',['ALL',...rs.map(r=>r.arm)],{ALL:'全部',...labels});renderCases();}
function filteredCases(){return DATA.cases.filter(c=>c.dataset===$('dataset').value&&c.group===$('group').value&&c.condition===$('condition').value&&($('fault').value==='ALL'||c.fault===$('fault').value)&&($('caseArm').value==='ALL'||c.arm===$('caseArm').value)&&c.case.toLowerCase().includes($('search').value.toLowerCase())&&($('caseState').value==='ALL'||($('caseState').value==='fixed'&&c.delta?.[0]>0)||($('caseState').value==='broken'&&c.delta?.[0]<0)||($('caseState').value==='problem'&&c.status!=='ok')));}
function renderCases(){let cs=filteredCases();$('caseCount').textContent=`符合 ${cs.length} 筆；頁面顯示前 ${Math.min(100,cs.length)} 筆，CSV 包含全部篩選結果。`;$('caseTable').querySelector('tbody').innerHTML=cs.slice(0,100).map(c=>`<tr><td>${escape(c.case)}</td><td>${escape(labels[c.arm])}</td><td>${c.root_rank??'未列出'}</td><td>${escape(c.status==='ok'?(c.delta?.[0]>0?'改對':c.delta?.[0]<0?'改錯':'第一名結果不變'):c.status+' '+c.error)}</td><td class="case-top">${c.top5.map(escape).join(' → ')}</td></tr>`).join('');}
$('download').onclick=()=>{let cs=filteredCases(),fields=['dataset','case','group','condition','arm','status','root_rank','top5'];let q=x=>'"'+String(Array.isArray(x)?x.join(' > '):x??'').replace(/"/g,'""')+'"';let s='\ufeff'+fields.join(',')+'\n'+cs.map(c=>fields.map(f=>q(c[f])).join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type:'text/csv;charset=utf-8'}));a.download='merit-filtered-cases.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('dataset').onchange=()=>cascade(1);$('group').onchange=()=>cascade(2);$('condition').onchange=()=>cascade(3);$('fault').onchange=render;$('metric').onchange=render;['caseArm','caseState'].forEach(id=>$(id).onchange=renderCases);$('search').oninput=renderCases;
$('nCases').textContent=Object.values(DATA.info.datasets).reduce((a,b)=>a+b,0);$('nRecords').textContent=DATA.info.real_records.toLocaleString();$('nErrors').textContent=DATA.info.errors+' / '+DATA.info.unsupported;$('overlap').textContent=`輸入檔案內容重複檢查：發現 ${DATA.info.duplicate_metric_files.length} 組完全相同的 metric 檔。沒有位元組重複也不代表統計獨立。`;
options('dataset',Object.keys(DATA.info.datasets),Object.fromEntries(Object.keys(DATA.info.datasets).map(s=>[s,s.toUpperCase()])));$('dataset').value='re2-ss';cascade(1);document.body.dataset.ready='true';
</script></body></html>'''

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--input',type=Path,required=True);args=ap.parse_args()
    data=json.loads((args.input/'analysis.json').read_text())
    text=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
    def ac(ds,arm,group='scale',condition='full'):
        r=next(r for r in data['summary'] if (r['dataset'],r['group'],r['condition'],r['arm'],r['fault'])==(ds,group,condition,arm,'ALL'))
        return f"{100*r['metrics']['AC@1']['value']:.2f}%"
    findings=''
    if not data['info'].get('smoke'):
        findings=f'''<section><h2>這次學到的四件事</h2><div class="explain">
<div class="card"><h3>先修退化尺度，比全面換 std 更值得追查</h3><p>只修 IQR=0 分母，RE2-SS 的 AC@1 從 {ac('re2-ss','original')} 到 {ac('re2-ss','fallback_only')}；OB 從 {ac('re2-ob','original')} 到 {ac('re2-ob','fallback_only')}。但 TT 從 {ac('re2-tt','original')} 降至 {ac('re2-tt','fallback_only')}，並非全系統勝出。</p></div>
<div class="card"><h3>乾淨基線下的提升，不代表抗污染</h3><p>全部改 std 後，三個 RE2 系統都對本輪污染很敏感。例如 TT 補入原正常樣本數 20% 的故障初期資料後，AC@1 從 {ac('re2-tt','median_std')} 降至 {ac('re2-tt','median_std','pollution','0.2')}。一個可能原因是故障資料放大正常尺度，讓真正異常看起來不再突出。</p></div>
<div class="card"><h3>換到 RE1，也有改善和退步</h3><p>median/std 在 RE1-SS 是 {ac('re1-ss','original')} → {ac('re1-ss','median_std')}；TT 是 {ac('re1-tt','original')} → {ac('re1-tt','median_std')}；OB 則是 {ac('re1-ob','original')} → {ac('re1-ob','median_std')}。這是固定公式的跨資料集結果，不是從未查看過的測試集。</p></div>
<div class="card"><h3>後段排序仍有情境差異</h3><p>同樣使用 median/std，OB 直接排序為 {ac('re2-ob','median_std','backend','direct')}，完整方法為 {ac('re2-ob','median_std')}；TT 直接排序為 {ac('re2-tt','median_std','backend','direct')}，完整方法為 {ac('re2-tt','median_std')}。不能只憑一個系統，宣布後段一定必要或一定多餘。</p></div>
</div><p class="muted">以上用 AC@1 說明主要現象；下方同時保留 AC@3／5、AVG@5、區間與改錯案例。這輪不自動更換正式預設。</p></section>'''
    (args.input/'index.html').write_text(PAGE.replace('__DATA__',text).replace('__FINDINGS__',findings))

if __name__=='__main__':main()
